#include <Loop.hpp>
#include <scalarselect_mod.hpp>
#include <complex>
#include <iostream>

using namespace scalarselect_mod;

complex loopI2(double p1, double m1, double m2, double mu2, int ep) {
    complex resQCDLoop, resOneLOop, loopI2_res;
    complex result[3]; // Equivalent to result(0:2)

    if ((scalarselect == 1) || (scalarselect == 3)) {
        resQCDLoop = qli2(p1, m1, m2, mu2, ep);
    }

    if (scalarselect == 1) {
        loopI2_res = resQCDLoop;
        return loopI2_res;
    }

    if (scalarselect == 3) {
        if ((std::abs(resOneLOop) > 1e-9) && (std::abs(resQCDLoop / resOneLOop - 1.0) > 1e-9)) {
            std::cout << "loopI2: " << p1 << ", " << m1 << ", " << m2 << ", " << mu2 << ", " << ep << std::endl;
            std::cout << "QCDLoop: " << resQCDLoop << std::endl;
            std::cout << "OneLOop: " << resOneLOop << std::endl;
            std::cout << "->ratio: " << resQCDLoop / resOneLOop << std::endl;
        }
    }

    return loopI2_res;
}

