// Local declarations for the QCDLoop C-bound scalar integrals used by this file.
// mod_qcdloop_c.f declares these via bind(C) without the VALUE attribute, so the
// Fortran ABI passes arguments by reference -- matched here with const references.
extern "C" {
  extern std::complex<double> qli2p(double const& p1, double const& m1, double const& m2, double const& mu2, int const& ep);
  extern std::complex<double> qli2pc(double const& p1, std::complex<double> const& m1, std::complex<double> const& m2, double const& mu2, int const& ep);
}

std::complex<double> loopI2p(double p1, double m1, double m2, double mu2, int ep) {
  std::complex<double> loopI2p_res, resQCDLoop, resOneLOop;
  std::complex<double> result[3]; // Equivalent to result(0:2)

  if (scalarselect == 1 || scalarselect == 3) {
    resQCDLoop = qli2p(p1, m1, m2, mu2, ep);
  }

  if (scalarselect == 1) {
    loopI2p_res = resQCDLoop;
    return loopI2p_res;
  }

  if (scalarselect == 3) {
    if (std::abs(resOneLOop) > 1e-9 && std::abs(resQCDLoop / resOneLOop - 1.0) > 1e-9) {
      std::cout << "loopI2p: " << p1 << ", " << m1 << ", " << m2 << ", " << mu2 << ", " << ep << std::endl;
      std::cout << "QCDLoop:" << resQCDLoop << std::endl;
      std::cout << "OneLOop:" << resOneLOop << std::endl;
      std::cout << "->ratio:" << resQCDLoop / resOneLOop << std::endl;
    }
  }

  return loopI2p_res;
}

std::complex<double> loopI2p(double p1, std::complex<double> m1, std::complex<double> m2, double mu2, int ep) {
  std::complex<double> loopI2p_res, resQCDLoop, resOneLOop;
  std::complex<double> result[3]; // Equivalent to result(0:2)

  if (scalarselect == 1 || scalarselect == 3) {
    resQCDLoop = qli2pc(p1, m1, m2, mu2, ep);
  }

  if (scalarselect == 1) {
    loopI2p_res = resQCDLoop;
    return loopI2p_res;
  }

  if (scalarselect == 3) {
    if (std::abs(resOneLOop) > 1e-12 && std::abs(resQCDLoop / resOneLOop - 1.0) > 1e-12) {
      std::cout << "loopI2p: " << p1 << ", " << m1 << ", " << m2 << ", " << mu2 << ", " << ep << std::endl;
      std::cout << "QCDLoop:" << resQCDLoop << std::endl;
      std::cout << "OneLOop:" << resOneLOop << std::endl;
      std::cout << "->ratio:" << resQCDLoop / resOneLOop << std::endl;
    }
  }

  return loopI2p_res;
}

extern "C" {
  std::complex<double> loopI2p_wrapper(double p1, double m1, double m2, double mu2, int ep) { // @coverage-probe
    return loopI2p(p1, m1, m2, mu2, ep);
  }

  std::complex<double> loopI2pc_wrapper(double p1, std::complex<double> m1, std::complex<double> m2, double mu2, int ep) { // @coverage-probe
    return loopI2p(p1, m1, m2, mu2, ep);
  }
}

